style.css:
@-moz-document domain("en.wikipedia.org"), domain("wikipedia.org") {
/* Wikipedia Hacker Green Glass v1.0.1 */
/* Canvas copied from ChatGPT Hacker Green v1.5.3. */
html {
  color-scheme: dark !important;
  color: #d9ffe6 !important;
  background-color: #0a0a0a !important;
  /* Entirely CSS-generated wallpaper: no image URLs or encoded assets. */
  /* Thin pale-green grid at 40px intervals, plus faint 4px CRT scan lines. */
  background-image:
    linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom,
      rgba(10,10,10,0) 0px,
      rgba(10,10,10,0) 3px,
      rgba(105,255,153,.035) 3px,
      rgba(105,255,153,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
}

html body,
body.skin-vector #content,
body.skin-vector .mw-page-container,
body.skin-vector .mw-page-container-inner,
body.skin-vector .vector-column-start,
body.skin-vector .vector-column-end,
body.skin-minerva .content,
body.skin-minerva #content,
body.skin-minerva #mw-mf-viewport,
body.skin-minerva #mw-mf-page-center {
  background-color: transparent !important;
  color: #d9ffe6 !important;
}

html, body, button, input, select, textarea, option, optgroup,
.central-featured-lang strong, .central-featured-lang small, .localized-slogan,
.mw-body h1, .mw-body h2, .mw-body h3, .mw-body h4, .mw-body h5,
.mw-body-content, .vector-toc, .minerva__tab-container, .cdx-button,
.oo-ui-widget, .oo-ui-inputWidget-input {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  font-variant-ligatures: none !important;
  font-feature-settings: "zero" 1 !important;
}

::selection { background: rgba(0,255,102,.35) !important; color: #f5fff7 !important; }
* { scrollbar-color: rgba(29,191,83,.53) rgba(0,18,7,.18); scrollbar-width: thin; }

body a, body a:visited, body .mw-parser-output a.external,
.central-featured-lang strong, .other-project-title {
  color: #68ffa3 !important;
}
body .mw-parser-output a.new, body .mw-parser-output a.new:visited { color: #70b68b !important; text-decoration: underline dotted !important; }
body .mw-parser-output a:visited { color: #9ee5b6 !important; }
body a:hover, body .mw-parser-output a:hover { color: #effff4 !important; }
body a:focus-visible, button:focus-visible, input:focus-visible, textarea:focus-visible,
select:focus-visible, summary:focus-visible, [tabindex]:focus-visible {
  outline: 2px solid #00ff66 !important;
  outline-offset: 2px !important;
}
input, textarea { caret-color: #38ff82 !important; }
input::placeholder, textarea::placeholder { color: #a6efbb !important; opacity: 1 !important; }
input[type="checkbox"], input[type="radio"], input[type="range"] { accent-color: #00ed61 !important; }

.central-featured-logo,
.mw-logo-icon,
.branding-box .branding-box-icon {
  filter: drop-shadow(0 0 4px rgba(0,255,102,.85)) drop-shadow(0 0 12px rgba(0,255,102,.35)) !important;
}
.central-textlogo__image,
.mw-logo-wordmark, .mw-logo-tagline,
.footer-sidebar .svg-Wikimedia-logo_black {
  filter: invert(1) sepia(1) saturate(1.4) hue-rotate(76deg) drop-shadow(0 0 4px rgba(0,255,102,.35)) !important;
}
.localized-slogan, .central-featured-lang small, .other-project-tagline, .suggestion-description,
.footer-sidebar-text, .smallprint, .styled-select, .vector-menu-heading,
.vector-page-toolbar, .mw-footer, .minerva-footer {
  color: #9ee5b6 !important;
}
.central-featured-lang .link-box, .other-project-link {
  background-color: rgba(3,33,17,.47) !important;
  border-radius: 10px !important;
  box-shadow: inset 0 0 0 1px rgba(32,243,107,.18) !important;
}
.central-featured-lang .link-box:hover, .central-featured-lang .link-box:focus-visible,
.other-project-link:hover, .other-project-link:focus-visible,
.langlist a:hover, .vector-menu-content a:hover, .vector-toc-link:hover,
.cdx-menu-item:hover, .suggestions-result:hover, .suggestions-result-current, .suggestion-link:hover, .suggestion-link.active {
  background-color: rgba(17,117,53,.40) !important;
  box-shadow: inset 2px 0 0 rgba(0,255,102,.76), 0 0 10px rgba(0,255,102,.09) !important;
}
.search-container .search-input {
  background-color: rgba(2,33,18,.42) !important;
  background-image: linear-gradient(125deg, rgba(21,100,54,.40) 0%, rgba(7,55,30,.28) 48%, rgba(1,20,13,.60) 100%) !important;
  border-radius: 10px 0 0 10px !important;
  backdrop-filter: blur(26px) saturate(160%) !important;
  -webkit-backdrop-filter: blur(26px) saturate(160%) !important;
}
.search-container .search-input input {
  background: transparent !important;
  border-color: rgba(85,255,143,.73) !important;
  border-radius: inherit !important;
}
.search-container .pure-button-primary-progressive {
  border-color: #00ed61 !important;
  border-radius: 0 10px 10px 0 !important;
}
.search-container .svg-search-icon { filter: brightness(0) !important; }
.styled-select .svg-arrow-down,
.lang-list-button .svg-language-icon, .lang-list-button .svg-arrow-down-blue {
  filter: brightness(0) saturate(100%) invert(.86) sepia(.35) saturate(1.5) hue-rotate(77deg) !important;
}
.lang-list-border, hr, .footer, .mw-body h1, .mw-body h2,
.vector-page-toolbar, .vector-menu-tabs, .mw-footer, .minerva-footer {
  border-color: rgba(28,240,102,.36) !important;
}
.lang-list-container, .footer-sidebar-content, .other-projects,
.vector-header, .vector-sticky-header, .vector-toc, .vector-main-menu,
.vector-page-tools, .vector-appearance, .minerva-header,
.mw-parser-output .infobox, .mw-parser-output .navbox,
.mw-parser-output .sidebar, .mw-parser-output .ambox, .mw-parser-output .toc,
.mw-parser-output .wikitable, .mw-parser-output .thumbinner,
figure[typeof="mw:File/Thumb"], figure[typeof="mw:File/Frame"], #catlinks,
.mw-search-profile-tabs, .mw-search-results-container, .mw-body .mw-warning {
  color: #d9ffe6 !important;
  background-color: rgba(3,30,14,.75) !important;
  border-color: rgba(28,240,102,.36) !important;
  border-radius: 10px !important;
  box-shadow: inset 0 0 0 1px rgba(32,243,107,.18) !important;
}
.lang-list-container, .footer-sidebar-content, .other-projects,
.vector-header, .vector-sticky-header, .vector-toc, .vector-main-menu,
.vector-page-tools, .vector-appearance, .minerva-header {
  background-color: rgba(2,24,13,.43) !important;
  background-image: linear-gradient(145deg, rgba(13,92,47,.35) 0%, rgba(4,47,25,.28) 40%, rgba(1,19,11,.59) 100%) !important;
  backdrop-filter: blur(26px) saturate(150%) !important;
  -webkit-backdrop-filter: blur(26px) saturate(150%) !important;
}
#searchInput, .cdx-text-input__input, .cdx-select-vue__handle,
textarea, select, .oo-ui-inputWidget-input,
button, input[type="button"], input[type="submit"], .cdx-button,
.oo-ui-buttonElement-button, .lang-list-button {
  color: #d9ffe6 !important;
  background-color: rgba(4,43,20,.95) !important;
  border-color: rgba(43,255,115,.44) !important;
}
.lang-list-button,
.lang-list-active .lang-list-button { outline-color: transparent !important; }
.lang-list-button:focus-visible,
.lang-list-active .lang-list-button:focus-visible { outline: 2px solid #00ff66 !important; }
.styled-select select { color: #d9ffe6 !important; background-color: transparent !important; }
option, optgroup { background-color: #03190b !important; color: #d9ffe6 !important; }
button:hover, input[type="button"]:hover, input[type="submit"]:hover,
.cdx-button:hover, .oo-ui-buttonElement-button:hover, .lang-list-button:hover {
  background-color: rgba(14,92,43,.63) !important;
  box-shadow: 0 0 12px rgba(0,255,102,.32) !important;
}
.pure-button-primary-progressive, .cdx-button--action-progressive.cdx-button--weight-primary,
.oo-ui-flaggedElement-progressive.oo-ui-flaggedElement-primary .oo-ui-buttonElement-button {
  color: #001708 !important;
  background-color: #00ed61 !important;
}
.pure-button-primary-progressive:hover, .cdx-button--action-progressive.cdx-button--weight-primary:hover {
  background-color: #38ff87 !important;
}
button:disabled, input:disabled, select:disabled, textarea:disabled { opacity: .62 !important; }
.suggestions-dropdown, .suggestions, .suggestions-results, .suggestions-special, .cdx-menu,
.cdx-typeahead-search__menu, .vector-dropdown-content, .mwe-popups,
.uls-menu, .oo-ui-popupWidget-popup, .oo-ui-window-frame, .cdx-dialog,
[role="dialog"], .mw-notification, .overlay-enabled .overlay,
.overlay-banner-main, .overlay-banner-mini, .frb-iad-dialog {
  background-color: rgba(2,23,11,.97) !important;
  color: #d9ffe6 !important;
  border-color: rgba(45,255,118,.50) !important;
  box-shadow: 0 8px 24px rgba(0,0,0,.28), 0 0 17px rgba(0,255,102,.12) !important;
}
.mw-body, .mw-body-content, .mw-body-content h1, .mw-body-content h2,
.mw-body-content h3, .mw-body-content h4, .mw-body-content h5,
.mw-parser-output figcaption, .thumbcaption, .vector-toc-text,
.mw-search-result-data, .searchmatch, .cdx-menu-item__text,
.cdx-search-result-title, .suggestion-title, .suggestions-result, .oo-ui-labelElement-label,
.mw-parser-output .reference-text, .vector-menu-tabs .selected a, .vector-dropdown-label, .mw-editsection {
  color: #d9ffe6 !important;
}
.mw-parser-output .wikitable th, .mw-parser-output .infobox th,
.mw-parser-output .navbox-title, .mw-parser-output .navbox-group,
.mw-parser-output .infobox-title, .mw-parser-output .infobox-header,
.mw-parser-output .navbox-abovebelow {
  background-color: rgba(6,46,22,.84) !important;
  color: #d9ffe6 !important;
  border-color: rgba(28,240,102,.36) !important;
}
.mw-parser-output .wikitable td, .mw-parser-output .navbox-list,
.mw-parser-output .infobox td {
  background-color: rgba(2,26,12,.82) !important;
  color: #d9ffe6 !important;
  border-color: rgba(32,243,107,.18) !important;
}
.mw-parser-output code, .mw-parser-output pre, .mw-parser-output .mw-highlight {
  color: #d9ffe6 !important;
  background-color: rgba(2,26,12,.82) !important;
  border-color: rgba(28,240,102,.36) !important;
}
.cdx-icon, .mw-ui-icon, .oo-ui-iconElement-icon, .oo-ui-indicatorElement-indicator,
.vector-dropdown-label::after, .vector-icon {
  color: #7fffac !important;
}
.mw-ui-icon::before, .oo-ui-iconElement-icon, .oo-ui-indicatorElement-indicator,
.vector-dropdown-label::after {
  filter: invert(.89) sepia(.33) saturate(1.5) hue-rotate(76deg) !important;
}
/* English Wikipedia Main Page: replace the section-specific fills. */
.mw-parser-output .mp-box,
.mw-parser-output #mp-banner {
  color: #d9ffe6 !important;
  background-color: rgba(3,30,14,.75) !important;
  border-color: rgba(28,240,102,.36) !important;
  border-radius: 10px !important;
  box-shadow: inset 0 0 0 1px rgba(32,243,107,.18) !important;
}
.mw-parser-output .mp-h2 {
  color: #d9ffe6 !important;
  background-color: rgba(6,46,22,.84) !important;
  border-color: rgba(28,240,102,.36) !important;
  border-radius: 6px !important;
}
}
